/* Stub ringan pengganti Cloudflare email-decode: membuka obfuskasi data-cfemail */
(function () {
  function dec(hex) {
    var key = parseInt(hex.substr(0, 2), 16), s = "";
    for (var i = 2; i < hex.length; i += 2) s += String.fromCharCode(parseInt(hex.substr(i, 2), 16) ^ key);
    return s;
  }
  function run() {
    document.querySelectorAll("[data-cfemail]").forEach(function (el) {
      var mail = dec(el.getAttribute("data-cfemail"));
      if (el.tagName === "A") el.href = "mailto:" + mail;
      el.textContent = mail;
      el.removeAttribute("data-cfemail");
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", run);
  else run();
})();
